<section class="panel"><div class="panel-head"><div><span class="panel-kicker">التواصل مع الزوار</span><h2>الإشعارات والنوافذ المنبثقة</h2></div></div>
<form method="post" action="/admin/site-notifications/save" class="form-grid popup-form"><?=csrf_field()?>
<label class="span-2">العنوان<input name="title" required></label><label class="span-2">الرسالة<textarea name="message" rows="4" required></textarea></label><label>اللغة<select name="locale"><option value="*">كل اللغات</option><?php foreach(enabled_locales() as $c=>$i):?><option value="<?=e($c)?>"><?=e(language_flag($c).' '.language_name($c))?></option><?php endforeach;?></select></label><label>نص الزر<input name="button_label" placeholder="اختياري"></label><label class="span-2">رابط الزر<input name="button_url" placeholder="https:// أو /page/..."></label><label>بداية الظهور<input type="datetime-local" name="starts_at"></label><label>نهاية الظهور<input type="datetime-local" name="ends_at"></label><label class="check-line"><input type="checkbox" name="active" value="1" checked> مفعّل</label><button class="btn btn-primary">إنشاء الإشعار</button></form>
<div class="popup-admin-list"><?php foreach($items as $n):?><article class="popup-admin-item"><div><strong><?=e($n['title'])?></strong><p><?=e($n['message'])?></p><small><?=e($n['locale'])?> · <?=e($n['starts_at']?:'الآن')?> → <?=e($n['ends_at']?:'بدون نهاية')?></small></div><form method="post" action="/admin/site-notifications/delete" onsubmit="return confirm('حذف الإشعار؟')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$n['id']?>"><button class="btn btn-danger">حذف</button></form></article><?php endforeach;?></div></section>
